# -*- coding: utf-8 -*-
"""دفعة 1 — تحديث 5 مقالات أحوال مدنية من البيانات الموثقة (sources-log.md 30/9/2026)
Atomic patch: يفشل كله أو ينفع كله — بدون تعديل جزئي."""
import re, sys, shutil

PATH = "articles.html"
BAK = "articles.html.bak-batch1"

# (عنوان المقال كمانر, المحتوى الجديد الموثق)
UPDATES = {
    "إزاي تتجدد بطاقتك الشخصية؟":
        r"""<h3>📋 الخطوات</h3><p>1. التقدم أونلاين بالكامل من <a href=\"https://digigate.gov.eg\" target=\"_blank\">بوابة مصر الرقمية</a> أو <a href=\"https://cso.moi.gov.eg\" target=\"_blank\">بوابة الأحوال المدنية</a></p><p>2. اكتب بياناتك وارفع المستندات المطلوبة</p><p>3. ادفع الرسوم: عادية 50ج (15 يوم) — عاجلة 125ج (3 أيام) — خاصة 175ج (24 ساعة) — VIP إكسبريس 515ج (30 دقيقة)</p><p>4. الاستلام بريد سريع للمنزل أو من السجل المدني</p><h3>📄 المستندات</h3><p>• البطاقة القديمة</p><p>• إثبات العنوان الجديد (لو غيرت سكنك)</p><p>• مستند من جهة العمل لو مر أكتر من 7 سنين على البطاقة السابقة (التقديم وقتها ورقيًا)</p><h3>⏰ إمتى لازم تتجدد؟</h3><p>البطاقة بتتجدد كل 7 سنين، أو لو غيرت عنوانك أو حالتك الاجتماعية</p><h3>💰 الغرامات</h3><p>• 100 جنيه لو اتعاملت ببطاقة منتهية أمام جهة رسمية</p><p>• 50 جنيه لو مجددتش بعد تغيير بياناتك</p><p>• 50 جنيه لو ما حدّثتش البيانات خلال 3 شهور من تغيرها</p>""",
    "إزاي تطلب شهادة ميلاد؟":
        r"""<h3>📋 الخطوات</h3><p>1. من مكتب السجل المدني: اكتب نموذج 40 (طلب صورة وثيقة رسمية)</p><p>2. أو أونلاين من <a href=\"https://digital.gov.eg\" target=\"_blank\">بوابة مصر الرقمية</a> (شرط: يوجد شهادة مميكنة مطبوعة سابقًا)</p><p>3. أو من الماكينات الذكية (العباسية، مطار القاهرة، شرم الشيخ، الغردقة) ومكاتب البريد</p><p>4. الاستلام: من السجل نفس اليوم، أو بالبريد خلال 3-10 أيام عمل</p><h3>💰 الرسوم الرسمية</h3><p>• أول مرة (مميكنة): 45 جنيه — نسخة مكررة: 25 جنيه</p><p>• ماكينة ذكية: 50 جنيه</p><p>• البريد: 55 جنيه (استلام من المكتب) / 65 جنيه (توصيل للمنزل)</p><p>• أونلاين: 65 جنيه أول مرة + 60 جنيه لكل نسخة إضافية</p><h3>📄 المستندات</h3><p>• الرقم القومي لصاحب الشأن أو للمولود</p><p>• بطاقة رقم قومي سارية لمقدم الطلب</p><h3>👥 مين له يطلبها؟</h3><p>صاحب الشأن، الأب، الأم، الأخ/الأخت، الزوج/الزوجة، الأبناء، الجد/الجدة، العم، الخال</p><h3>⏰ قيد المواليد</h3><p>سجّل المولود خلال 15 يوم من الولادة في مكتب الصحة — والمواليد في الخارج خلال 3 شهور من القنصلية المصرية</p>""",
    "إزاي تطلب بدل فاقد لبطاقتك؟":
        r"""<h3>📋 الخطوات</h3><p>1. حرّر محضر فقد من قسم الشرطة أولاً (البطاقة التالفة مش محتاجة محضر)</p><p>2. قدّم طلب بدل فاقد/تالف أونلاين من <a href=\"https://digigate.gov.eg\" target=\"_blank\">بوابة مصر الرقمية</a> أو حضوريًا من السجل المدني</p><p>3. ادفع الرسوم — نفس فئات الاستمارات: عادية 50ج (15 يوم) — عاجلة 125ج (3 أيام) — خاصة 175ج (24 ساعة) — VIP إكسبريس 515ج (30 دقيقة)</p><p>4. الاستلام من السجل أو بالبريد السريع</p><h3>📄 المستندات</h3><p>• محضر الفقد من قسم الشرطة</p><p>• البطاقة التالفة (في حالة التلف)</p><p>• صورة شخصية حديثة</p><h3>⏰ مهم!</h3><p>غرامة 50 جنيه لو اتأخرت أكتر من 15 يوم من تاريخ المحضر</p><h3>💡 نصيحة</h3><p>لو سرقولك البطاقة، المحضر بيساعدك تتجنب أي مسؤولية عن إساءة استخدامها</p>""",
    "إزاي تستخرج شهادة وفاة؟":
        r"""<h3>📋 الخطوات</h3><p>1. بلّغ عن الوفاة خلال 24 ساعة لمكتب الصحة + استلم تصريح الدفن</p><p>2. الشهادة الأولى بتستلم من مكتب الصحة فقط</p><p>3. النسخ المميكنة (نموذج 40) من السجل المدني بـ25 جنيه</p><p>4. أو أونلاين من <a href=\"https://digital.gov.eg\" target=\"_blank\">بوابة مصر الرقمية</a> (شرط: شهادة مميكنة مطبوعة سابقًا + قريب درجة أولى)</p><h3>📄 المستندات</h3><p>• تصريح الدفن من المستشفى أو مكتب الصحة</p><p>• بطاقة الرقم القومي للمتوفي (لو متاحة)</p><p>• بطاقة الرقم القومي لمقدم الطلب (قريب درجة أولى)</p><h3>💰 الرسوم</h3><p>الشهادة المميكنة: 25 جنيه</p><h3>⏰ مهم!</h3><p>التبليغ خلال 24 ساعة — والشهادة المترجمة للاستخدام في الخارج بتاخد 3-5 أيام عمل</p>""",
    "إزاي تسجّل عقد زواج؟":
        r"""<h3>📋 الخطوات</h3><p>1. روح لمكتب توثيق الزواج (المأذون) — الزوجين حاضرين شخصيًا مع شاهدين</p><p>2. اكتب عقد الزواج ووقّع الطرفان والشهود</p><p>3. ادفع الرسوم (600 جنيه + نسبة من المؤخر لو موجود)</p><p>4. استلم وثيقة الزواج الرسمية</p><h3>📄 المستندات</h3><p>• بطاقة الرقم القومي للزوجين</p><p>• شهادة ميلاد الزوجين</p><p>• شهادة الطب الشرعي (لكلا الطرفين)</p><p>• شاهدان ذكران</p><h3>💰 المصاريف</h3><p>بدون مؤخر: 600 جنيه | مؤخر أقل من 5000: 600 + 3% | أقل من 10000: 600 + 4% | أكبر: 600 + 5% | طلاق حضوري/مراجعة: 600 | طلاق غيابي: 800</p><h3>📤 عايز نسخة من وثيقة قديمة؟</h3><p>قسيمة الزواج الإلكترونية 70 جنيه (تصدر خلال 7 أيام عمل) — أو من السجل المدني نفس اليوم/24 ساعة — متاح لمن أُطبعت وثيقته بعد أبريل 1962</p>""",
}

src = open(PATH, encoding="utf-8").read()
shutil.copyfile(PATH, BAK)
count_before = src.count("title:'")
problems = []
for title, new_content in UPDATES.items():
    esc = re.escape(title)
    pattern = re.compile(r"(title:'" + esc + r"'.*?content:`)[^`]*(`)", re.DOTALL)
    if len(pattern.findall(src)) != 1:
        problems.append(title); continue
    src = pattern.sub(lambda m: m.group(1) + new_content + m.group(2), src, count=1)

if problems:
    open(PATH, "w", encoding="utf-8").write(open(BAK, encoding="utf-8").read())
    sys.exit("فشل التطابق لمقالات: " + ", ".join(problems) + " — تم التراجع")

if src.count("title:'") != count_before or src.count("content:`") != count_before:
    sys.exit("عدد المقالات اتغير! — لم يتم الحفظ")

open(PATH, "w", encoding="utf-8").write(src)
checks = ["45 جنيه — نسخة مكررة: 25", "خلال 24 ساعة لمكتب الصحة", "أكتر من 15 يوم من تاريخ المحضر",
          "بوابة الأحوال المدنية", "قسيمة الزواج الإلكترونية 70 جنيه"]
print("OK — تم تحديث 5 مقالات، عدد المقالات الكلي:", count_before)
for c in checks:
    print(("✓ " if c in src else "✗ مفقود ") + c)
